#!/usr/bin/env python3
"""Generate C-grid acoustic boundary Metal arithmetic from authoritative GLSL."""
import argparse
import re
from generate_tke_msl import ROOT, translate


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "metal/include/compute/metal/shaders/dynamics/acoustic_bc_face_cartesian_cgrid_msl.hpp"
    source = translate("acoustic_bc_face_cartesian_cgrid", "dynamics").replace(
        "Generated by scripts/dev/shaders/generate_tke_msl.py",
        "Generated by scripts/dev/shaders/generate_acoustic_bc_face_cartesian_cgrid_msl.py",
    )
    for name in ("dt_phase", "tendency", "increment", "result"):
        source = re.sub(rf"\bfloat\s+{name}\s*=", lambda m: "volatile " + m[0], source)
    source = source.replace("umulExtended(x, y, high, low);",
                            "high = uint((ulong(x) * ulong(y)) >> 32); low = x * y;")
    if args.check:
        if not path.exists() or path.read_text() != source:
            raise SystemExit("acoustic-boundary Metal source is stale")
    else:
        path.write_text(source)


if __name__ == "__main__":
    main()
